}

.limited-card .availability-badge {
  position: absolute;
  top: -2px;
  left: -2px;
  font-family: var(--font-accent);
  font-size: 9px;
  background: var(--acid-circuit);
  color: var(--void-black);
  padding: 6px 10px;
  letter-spacing: 0.06em;
  z-index: 3;
}

/* ============================================================
   MERCH — Why shop (feature grid 4-up)
   ============================================================ */
.section-whyshop {
  background: var(--void-black);
  padding: 96px 0;
}

.whyshop-header h2 {
  font-size: clamp(2rem, 5vw, 3.2rem);
  color: var(--datastream-white);
  margin-top: 12px;
}
.whyshop-header h2 .key { color: var(--neon-cyan); }

.whyshop-divider {
  height: 1px;
  background: var(--deadzone-charcoal);
  margin: 28px 0 56px;
}

.whyshop-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}

.whyshop-item {
  border-top: 0;
}

.whyshop-item .rule {
  width: 32px;
  height: 2px;
  background: var(--plasma-violet);
