}

.whyshop-item h3 {
  font-family: var(--font-display);
  font-weight: 700;
  text-transform: uppercase;
  font-size: 16px;
  letter-spacing: -0.02em;
  color: var(--neon-cyan);
  margin-bottom: 8px;
}

.whyshop-item p {
  font-size: 15px;
  color: rgba(232, 238, 255, 0.85);
}

/* ============================================================
   MERCH — Section 5 close (gradient)
   ============================================================ */
.section-merch-close {
  background: linear-gradient(135deg, var(--plasma-violet) 0%, var(--void-black) 75%);
  padding: 100px 0;
  position: relative;
  overflow: hidden;
  clip-path: polygon(0 32px, 100% 0, 100% 100%, 0 100%);
  margin-top: -32px;
}

.section-merch-close .container {
  text-align: center;
  max-width: 720px;
  position: relative;
  z-index: 2;
}

.section-merch-close h2 {
  font-size: clamp(2rem, 5vw, 4rem);
  color: var(--neon-cyan);
  margin: 24px 0;
}
.section-merch-close h2 .grid-word { color: var(--rift-magenta); }

.section-merch-close p {
  color: var(--datastream-white);
  margin-bottom: 36px;
  max-width: 480px;
  margin-left: auto;
  margin-right: auto;
}

.tagline-echo {
  margin-top: 48px;
  font-family: var(--font-accent);
  font-size: 9px;
  letter-spacing: 0.12em;
  color: var(--deadzone-charcoal);
  filter: brightness(1.4);
}

/* ============================================================
   CONTACT — Header
   ============================================================ */
.contact-header {
  background: var(--void-black);
  padding: 80px 0 64px;
  position: relative;
  overflow: hidden;
  min-height: 420px;
  display: flex;
  align-items: center;
}

.magenta-slash {
  position: absolute;
  bottom: -10%;
  left: -10%;
  width: 70%;
  height: 60%;
  background: var(--rift-magenta);
  clip-path: polygon(0 100%, 100% 0, 100% 100%);
  z-index: 0;
}

.magenta-slash::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: repeating-linear-gradient(
    to bottom,
    rgba(170, 255, 0, 0.08) 0px,
    rgba(170, 255, 0, 0.08) 1px,
    transparent 1px,
    transparent 4px
  );
  pointer-events: none;
}

.contact-header .container {
  position: relative;
  z-index: 2;
}

.contact-header .eyebrow-row {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 20px;
}

.contact-header .eyebrow-row .rule {
  width: 32px;
  height: 1px;
  background: var(--rift-magenta);
}

.contact-header h1 {
  font-size: clamp(36px, 7vw, 80px);
  color: var(--neon-cyan);
  max-width: 75%;
  margin-bottom: 24px;
}

.contact-header h1 .punct-magenta {
  color: var(--rift-magenta);
  text-shadow: 0 0 8px rgba(255, 0, 128, 0.4);
}

.contact-header .sub {
  max-width: 560px;
  color: var(--datastream-white);
  font-size: 16px;
  line-height: 1.65;
}

/* ============================================================
   CONTACT — Channel cards
   ============================================================ */
.section-channels {
  background: var(--grid-steel);
  padding: 80px 0;
}

.channels-header { margin-bottom: 40px; max-width: 50%; }
.channels-header h2 {
  font-size: clamp(2rem, 4vw, 3.2rem);
  color: var(--neon-cyan);
  margin-top: 12px;
}
.channels-header p {
  margin-top: 14px;
  color: var(--datastream-white);
  font-size: 15px;
}

.channels-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.channel-card {
  background: var(--deadzone-charcoal);
  border: 1px solid rgba(0, 245, 255, 0.4);
  padding: 28px;
  transition: all 0.25s ease;
}
.channel-card:hover {
  border-color: var(--neon-cyan);
  background: #393955;
  box-shadow: 0 0 16px rgba(0, 245, 255, 0.4);
  transform: translateY(-2px);
}

.channel-icon {
  width: 40px;
  height: 40px;
  color: var(--neon-cyan);
