}

.channel-card h3 {
  font-family: var(--font-display);
  font-weight: 700;
  text-transform: uppercase;
  font-size: 20px;
  letter-spacing: -0.03em;
  color: var(--datastream-white);
  margin-bottom: 12px;
}

.channel-card .desc {
  font-size: 14px;
  color: rgba(232, 238, 255, 0.8);
  margin-bottom: 20px;
}

.channel-card .email-rule {
  height: 1px;
  background: rgba(170, 255, 0, 0.6);
  margin-bottom: 12px;
